import {
  getSecureItem,
  removeSecureItem,
  setSecureItem,
  type SecureStorageConfig,
} from '@linm-soft-org/linm-web-common-components';

export const LINM_LAST_USERNAME_KEY = 'linm_last_username';

const CONFIG: SecureStorageConfig = {
  storageKey: LINM_LAST_USERNAME_KEY,
  version: 1,
  hashKey: 'ui.lastUsername',
};

export function getLastUsername(): string {
  return getSecureItem<string>(CONFIG, { allowLegacyPlain: true }) || '';
}

export function setLastUsername(username: string): void {
  setSecureItem(CONFIG, username);
}

export function clearLastUsername(): void {
  removeSecureItem(CONFIG);
}
