import * as XLSX from 'xlsx';
import type { AdminAccountListItem } from '../services/admin';

function accountDisplayName(item: AdminAccountListItem): string {
  return item.fullName.trim() || item.username;
}

function buildFileName(companyLabel?: string, scope?: 'all' | 'page', page?: number): string {
  const date = new Date().toLocaleDateString('vi-VN', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).replace(/\//g, '-');
  const companySuffix = companyLabel
    ? `-${companyLabel.replace(/[^\w\u00C0-\u024F\u1E00-\u1EFF-]+/g, '_').slice(0, 40)}`
    : '';
  const scopeSuffix = scope === 'page' && page ? `-trang-${page}` : '';
  return `tra-cuu-tai-khoan${companySuffix}${scopeSuffix}-${date}.xlsx`;
}

/** Export tra cứu tài khoản — columns: Tài khoản (họ tên), Username. */
export function exportAccountLookupExcel(
  items: AdminAccountListItem[],
  companyLabel?: string,
  scope?: 'all' | 'page',
  page?: number,
): void {
  const rows = items.map((item) => ({
    'Tài khoản': accountDisplayName(item),
    Username: item.username,
  }));
  const sheet = XLSX.utils.json_to_sheet(rows);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, sheet, 'Tai khoan');
  XLSX.writeFile(workbook, buildFileName(companyLabel, scope, page));
}
