import {
  clearActiveCompanyCode,
  clearAuthTokens,
  clearAuthUser,
  hasValidAuthToken,
  setActiveCompanyCode,
  setAuthTokens,
  setAuthUser,
} from '@linm-soft-org/linm-web-common-components';
import type { User } from '@linm-soft-org/linm-web-common-components';
import { UserRole } from '@linm-soft-org/linm-web-common-components';

/** Default tenant for standalone dev — company code (X-Company-Id), not Guid. */
export const STANDALONE_DEFAULT_COMPANY_CODE =
  (import.meta.env.VITE_DEV_COMPANY_CODE as string | undefined)?.trim() || 'LINM';

export const STANDALONE_MOCK_USER: User = {
  id: '00000000-0000-0000-0000-000000000001',
  username: 'dev.standalone',
  email: 'dev@linm.local',
  firstName: 'Dev',
  lastName: 'Standalone',
  fullName: 'Dev Standalone',
  role: UserRole.Admin,
  departmentId: '00000000-0000-0000-0000-000000000002',
  departmentName: 'Phòng phát triển',
  skills: [],
  isActive: true,
  package: 'Staff',
  companyCode: STANDALONE_DEFAULT_COMPANY_CODE,
  allowedCompanyCodes: [STANDALONE_DEFAULT_COMPANY_CODE],
  canViewAllCompanies: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
};

/** JWT-shaped access token — required by hasValidAuthToken(). */
const MOCK_ACCESS_TOKEN =
  'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJkZXYuc3RhbmRhbG9uZSJ9.standalone-dev-mock-signature';

const MOCK_REFRESH_TOKEN = 'standalone-dev-refresh-token-000000000000000000';

/** Seed auth for standalone — skips if real session already exists (unless force). */
export function seedStandaloneAuth(force = false): void {
  if (!force && hasValidAuthToken()) return;
  setAuthTokens({ accessToken: MOCK_ACCESS_TOKEN, refreshToken: MOCK_REFRESH_TOKEN });
  setAuthUser(STANDALONE_MOCK_USER);
  setActiveCompanyCode(STANDALONE_DEFAULT_COMPANY_CODE);
}

export function clearStandaloneAuth(): void {
  clearAuthTokens();
  clearAuthUser();
  clearActiveCompanyCode();
}
